def run_repl(runtime: Runtime) -> int:
    banner_printed = False
    sys.stdout.write(VERSION_BANNER + "\n")
    sys.stdout.flush()
    banner_printed = True
    buffer: list[str] = []
    prompt = "> "
    while True:
        try:
            line = input(prompt)
        except EOFError:
            if not buffer:
                if banner_printed:
                    sys.stdout.flush()
                return 0
            line = ""
        buffer.append(line)
        source = "\n".join(buffer)
        chunk: Optional[Chunk] = None
        expr_mode = False
        try:
            try:
                chunk = compile_for_repl("stdin", source, expr_mode=True)
                expr_mode = True
            except LuaParseError as expr_err:
                if expr_err.incomplete:
                    prompt = ">> "
                    continue
                chunk = compile_for_repl("stdin", source, expr_mode=False)
        except LuaParseError as err:
            if err.incomplete:
                prompt = ">> "
                continue
            runtime.stderr.write(err.format_message() + "\n")
            runtime.stderr.flush()
            buffer.clear()
            prompt = "> "
            continue
        runtime._current_source_text = source
        try:
            results = run_generator(runtime.exec_chunk(chunk))
            if expr_mode and results:
                runtime.lib_print(*results)
        except LuaExit as ex:
            return ex.code
        except LuaRuntimeError as err:
